"""ALGORITHM BIAS - interactive Y2K magazine research report.   Run:  streamlit run app.py
Every number is read from results/ and data/raw/. Missing file = visible error, never invented data."""
import json
from pathlib import Path
import pandas as pd
import streamlit as st
import streamlit.components.v1 as components

ROOT = Path(__file__).resolve().parent
RES, RAW = ROOT / "results", ROOT / "data" / "raw"
st.set_page_config(page_title="ALGORITHM BIAS", page_icon="💿", layout="wide", initial_sidebar_state="collapsed")
st.markdown("""<style>
#MainMenu,footer,header,[data-testid="stSidebar"],[data-testid="stToolbar"]{display:none!important}
.stApp,.stApp>div{background:#2f7bff!important;color-scheme:light}.block-container{padding:0!important;max-width:100%!important}
iframe{height:100vh!important;border:0;display:block}
</style>""", unsafe_allow_html=True)

REQUIRED = {"models": "model_comparison.csv", "weights": "weight_sensitivity_summary.csv",
            "sampling": "sensitivity_summary.csv", "creators": "creator_simulation.csv", "rounds": "round_metrics.csv"}
missing = [f for f in REQUIRED.values() if not (RES / f).exists()]
if missing:
    st.error("Missing result files in `results/`: " + ", ".join(missing) + ". Re-run the scripts in README.md.")
    st.stop()


@st.cache_data
def raw_shape(name):
    p = RAW / name
    if p.exists():
        return [len(pd.read_csv(p, usecols=[0])), len(pd.read_csv(p, nrows=0).columns)]
    j = RES / "dataset_shapes.json"          # used when raw data is not uploaded (e.g. free cloud hosting)
    return json.loads(j.read_text()).get(name) if j.exists() else None


@st.cache_data
def build_data():
    d = {k: pd.read_csv(RES / f) for k, f in REQUIRED.items()}
    dist = {p: [round(v, 5) for v in g["simulated_visibility_share"].sort_values(ascending=False)]
            for p, g in d["creators"].groupby("policy")}
    series = {p: g.sort_values("round")[["round", "exposure_gini_so_far"]].round(4).values.tolist()
              for p, g in d["rounds"].groupby("policy")}
    return {"models": d["models"].round(6).to_dict("records"), "weights": d["weights"].round(4).to_dict("records"),
            "sampling": d["sampling"].round(4).to_dict("records"), "dist": dist, "series": series,
            "rawA": raw_shape("Instagram_Analytics.csv"), "rawB": raw_shape("social_media_dataset.csv")}


